// Empty when an op of these counts fits the schema, else why not (checked as each op is recorded).
inline std::string check(int op, int nsrc, int nip, int nfp)
{
    const OpSignature* s = signature(op);
    if (s == nullptr) return "graph builder: unknown op " + std::to_string(op);
    auto bad = [&](const char* what, int n, int lo, int hi) {
        return std::string("graph builder: ") + s->name + " takes " + std::to_string(lo) + (lo == hi ? "" : ".." + std::to_string(hi)) + " " + what
            + ", the program gave " + std::to_string(n);
    };
    if (nsrc < s->srcs_min || nsrc > s->srcs_max) return bad("operands", nsrc, s->srcs_min, s->srcs_max);
    if (nip < s->ip_min || nip > s->ip_max) return bad("integer parameters", nip, s->ip_min, s->ip_max);
    if (nfp < s->fp_min || nfp > s->fp_max) return bad("float parameters", nfp, s->fp_min, s->fp_max);
    return std::string();
}

